        r_part = [row[sr+1:] for row in grid]
        n_cols = min(len(l_part[0]), len(r_part[0]))
        return [[2 if l_part[r][c] == 0 and r_part[r][c] == 0 else 0 for c in range(n_cols)] for r in range(min(len(l_part), len(r_part)))]
